	@Test
	void deferredBulkRecordsPreserveDictionaryAndNativeCatalog() throws Exception {
		LmdbStoreConfig config = config();
		StoreProperties properties = new StoreProperties(directory.toFile());
		LmdbStoreFormat format = LmdbStoreFormat.forNewStore(config);
		format.initializeProperties(properties);
		BNode node = SimpleValueFactory.getInstance().createBNode("fenced");
		long id = ValueIds.createId(ValueIds.T_BNODE, 11L);
		byte[] data = ValueStoreRecordCodec.bnodeData(node);
		List<ValueStore.BulkRecord> records = new ArrayList<>(List.of(
				new ValueStore.BulkRecord(data, ValueStoreRecordCodec.idKey(id)),
				new ValueStore.BulkRecord(ValueStoreRecordCodec.idKey(id), data)));
		records.sort((left, right) -> Arrays.compareUnsigned(left.key(), right.key()));
		var input = records.iterator();
		ValueStore values = new ValueStore(directory.resolve("values").toFile(), properties, config, true,
				null, format, true);
		try {
			values.appendBulkRecords(() -> input.hasNext() ? input.next() : null, 1, 1024L);
			assertThat(values.getValue(id)).isEqualTo(node);
			assertThat(values.getId(node, false)).isEqualTo(id);
			byte[] fence = values.getTxnManager().doWithPriority((stack, txn) -> readFence(stack, txn));
			assertThat(fence).containsExactly((byte) 6);
		} finally {
			values.close();
		}
	}

	@Test
	void fencedNewStoreStillUsesFreshPreparedDictionaryWriter() throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		store.init();
		try {
			ValueStore values = (ValueStore) store.getValueFactory();
			assertThat(values.getFormat().usesCoreDatatypeLiteralReferences()).isTrue();
			assertThat(values.getFormat().getVersion()).isEqualTo(6);
			byte[] fence = values.getTxnManager().doWithPriority((stack, txn) -> readFence(stack, txn));
			assertThat(fence).containsExactly((byte) 6);
			var literal = SimpleValueFactory.getInstance().createLiteral("fresh prepared dictionary identity");
			values.startTransaction(true);
			ValueStore.FreshValueSession session = values.startFreshValueSessionIfEmpty();
			assertThat(session).as("catalog entries must not count as RDF dictionary owners").isNotNull();
			ValueStore.PreparedValueBatch batch = values.prepareFreshValues(session, new Value[] { literal });
			long id = batch.ids()[0];
			values.persistPreparedValues(batch);
			values.commit();
			values.commitFreshValueTransaction(session);
			values.publishPreparedValues(batch);
			values.discardFreshValueSession(session);
			assertThat(values.getValue(id)).isEqualTo(literal);
			try (NotifyingSailConnection connection = store.getConnection()) {
				var vf = SimpleValueFactory.getInstance();
				connection.begin();
				connection.addStatement(vf.createIRI("urn:fence:fresh"), vf.createIRI("urn:fence:predicate"), literal);
				connection.commit();
				assertThat(values.getId(literal, false)).isEqualTo(id);
			}
		} finally {
			store.shutDown();
		}
	}

